Subject: [PATCH] applets/taskmanager: raise active task covered by other
 windows on click

With focus follows mouse the active window can sit below other windows,
and clicking its task minimized it instead of bringing it up. Now the
click only minimizes when no window that it can rise above overlaps it.

BUG: 365948
---
 applets/taskmanager/qml/code/TaskTools.js | 52 ++++++++++++++++++++++-
 applets/taskmanager/qml/main.qml          |  1 +
 2 files changed, 52 insertions(+), 1 deletion(-)

diff --git a/applets/taskmanager/qml/code/TaskTools.js b/applets/taskmanager/qml/code/TaskTools.js
index 8f8adadd6f..24d5d883d5 100644
--- a/applets/taskmanager/qml/code/TaskTools.js
+++ b/applets/taskmanager/qml/code/TaskTools.js
@@ -116,6 +116,56 @@ function groupTopTask(childTaskList, attribute, tasks) {
     return topTaskIndex;
 }

+// Whether another window that can't stay above this one when it's raised
+// covers part of it, e.g. an active window below others with focus follows mouse
+function isCoveredByOtherWindow(index, tasks) {
+    const model = tasks.tasksModel;
+    const data = (modelIndex, role) => model.data(modelIndex, role);
+    const layer = modelIndex => data(modelIndex, TaskManager.AbstractTasksModel.IsKeepAbove) ? 2
+        : data(modelIndex, TaskManager.AbstractTasksModel.IsKeepBelow) ? 0 : 1;
+
+    const geometry = data(index, TaskManager.AbstractTasksModel.Geometry);
+    const stackingOrder = data(index, TaskManager.AbstractTasksModel.StackingOrder);
+    const currentDesktop = tasks.virtualDesktopInfo.currentDesktopByScreenGeometry(data(index, TaskManager.AbstractTasksModel.ScreenGeometry));
+
+    const covers = other => {
+        if (data(other, TaskManager.AbstractTasksModel.IsGroupParent)
+            || data(other, TaskManager.AbstractTasksModel.IsActive)
+            || data(other, TaskManager.AbstractTasksModel.IsMinimized)
+            || data(other, TaskManager.AbstractTasksModel.StackingOrder) <= stackingOrder
+            || layer(other) > layer(index)) {
+            return false;
+        }
+
+        const desktops = data(other, TaskManager.AbstractTasksModel.VirtualDesktops);
+        const activities = data(other, TaskManager.AbstractTasksModel.Activities);
+        if (!data(other, TaskManager.AbstractTasksModel.IsOnAllVirtualDesktops) && desktops.indexOf(currentDesktop) < 0) {
+            return false;
+        }
+        if (activities.length > 0 && activities.indexOf(model.activity) < 0) {
+            return false;
+        }
+
+        const otherGeometry = data(other, TaskManager.AbstractTasksModel.Geometry);
+        return otherGeometry.x < geometry.x + geometry.width && geometry.x < otherGeometry.x + otherGeometry.width
+            && otherGeometry.y < geometry.y + geometry.height && geometry.y < otherGeometry.y + otherGeometry.height;
+    };
+
+    for (let i = 0; i < model.count; ++i) {
+        const other = model.makeModelIndex(i);
+        if (covers(other)) {
+            return true;
+        }
+        for (let j = 0; j < model.rowCount(other); ++j) {
+            if (covers(model.makeModelIndex(i, j))) {
+                return true;
+            }
+        }
+    }
+
+    return false;
+}
+
 function activateTask(index, model, modifiers, task, plasmoid, tasks, windowViewAvailable) {
     if (modifiers & Qt.ShiftModifier) {
         tasks.tasksModel.requestNewInstance(index);
@@ -210,7 +260,7 @@ function activateTask(index, model, modifiers, task, plasmoid, tasks, windowView
         if (model.IsMinimized) {
             tasks.tasksModel.requestToggleMinimized(index);
             tasks.tasksModel.requestActivate(index);
-        } else if (model.IsActive && plasmoid.configuration.minimizeActiveTaskOnClick) {
+        } else if (model.IsActive && plasmoid.configuration.minimizeActiveTaskOnClick && !isCoveredByOtherWindow(index, tasks)) {
             tasks.tasksModel.requestToggleMinimized(index);
         } else {
             tasks.tasksModel.requestActivate(index);
